def largest_perfect_square(n):
    # Factor n into its prime factors
    factors = []
    divisor = 2
    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1
    if n > 1:
        factors.append(n)
    # Calculate the largest perfect square divisor
    ks = 0
    t = 1
    for i in range(len(factors) - 1, -1, -1):
        temp = factors[i]
        count = 1
        while temp % 2 == 0:
            count += 1
            temp //= 2
        if count % 2 == 1:
            t *= pow(temp, (1 + (count - 1) // 2), t)
        t %= divisor
    return int(t)

