from collections import defaultdict

def next_bigger(s):
    """Yield the lexicographically next bigger string."""
    i = len(s) - 2
    while i >= 0 and s[i] >= s[i + 1]:
        i -= 1
    if i == -1:
        return s
    j = len(s) - 1
    while j > i and s[j] <= s[i]:
        j -= 1
    s[i], s[j] = s[j], s[i]
    s[i+1:] = reversed(s[i+1:])
    return ''.join(s)

