import sys
from heapq import heappush, heappop

def solve(n, P, W, queries):
    stack = []
    inverting_points = []
    imbalance = 0

    for i, w in enumerate(W):
        heappush(stack, (w, i + 1))
        stack.sort()

        while len(stack) > n + 1:
            w_i, i_i = heappop(stack)
            if i_i - 1 > max(W[i_i-2:i_i]):
                imbalance += W[i_i-1]
                inverting_points.append((W[i_i-1], i_i - 1, i_i - 2))

        if len(stack) < n:
            w_j, j = heappop(stack)
            imbalance += W[j]
            inverting_points.append((W[j], j, j + 1))

    def best_imp_event(num, start, weights):
        left_weights = []
        ans = 0
        current = weights[num - start]

        for next_num in range(num + 1, n):
            next_weight = weights[next_num]

            if current + next_weight < 0:
                left_weights.append(next_weight)
                best_imp_event(next_num, num, weights)

            elif current + next_weight > 0:
                ans += abs(current)
                current = next_weight
            else:
                break

        for left_weight in left_weights:
            while w := inverting_points[i := left_weight]:
                if w[1] in range(num + 1, start + 1):
                    break
                w, i, num_i = w
                if abs(imbalance - w) < abs(imbalance - 2 * w):
                    total = abs(imbalance - w) + abs(imbalance - 2 * left_weight)
                    if weights[n - 1] + left_weight < 0:
                        total += weights[start]
                elif weights[(n - 2) - num_i] + left_weight < 0:
                    total += weights[(n - 2) - num_i]
                else:
                    total += abs(imbalance) + abs(weights[num_i - 1])

                if ans > total:
                    ans = total

                    heappush(stack, (w, num_i - 1))

            imbalance -= w

        return ans

    result = []

    for X, Y in queries:
        current_imbalance = sum(W[i] * abs(i - X) for i in range(n) if i > X)
        ans = best_imp_event(Y, X, W)
        ans -= 2 * current_imbalance
        result.append(ans)

    return result

