def build_tree(edges: List[Tuple[int, int, int, int]]) -> List[Tuple[int, int, int, int]]:
    n = len(edges) + 1
    parent = collections.defaultdict(lambda: -1)
    depth = collections.defaultdict(lambda: 0)

    for from_vertex, to_vertex, weight, strength in edges:
        parent[to_vertex] = from_vertex

    def get_depth(vertex):
        if vertex == 1:
            return 0
        return depth[vertex] + get_depth(parent[vertex])

    for vertex, _, _, _ in edges:
        depth[vertex] = get_depth(parent[vertex])

    topological_order = []
    def dfs(vertex):
        nonlocal topological_order
        topological_order.append(vertex)

        for next_vertex in range(1, n + 1):
            if parent[next_vertex] == vertex:
                dfs(next_vertex)

    dfs(1)

    result_edges = []
    for vertex, next_vertex, weight, strength in sorted(edges, key=lambda edge: weight):
        result_edges.append((vertex, next_vertex, weight, strength))

        if next_vertex < n:
            result_edges.append((next_vertex, vertex, weight, 0))

    return [' '.join(map(str, edge)) for edge in result_edges]

def can_break_edge(parent: int, child: int, weight_diff: int, child_weight: int, strength_diff: int) -> bool:
    return child_weight + (child_weight // weight_diff) <= child_weight + strength_diff

