from collections import deque, defaultdict

def longest_common_subsequence(t, s):
    t_dict = defaultdict(list)
    s_dict = defaultdict(list)

    for i in range(len(t)):
        if len(t[i]) > 1:
            for j in range(len(t[i])):
                t_dict[t[i][j]].append(i)
    for i in range(len(s)):
        if len(s[i]) > 1:
            for j in range(len(s[i])):
                s_dict[s[i][j]].append(i)

    dp = [[0 for _ in range(len(t) + 1)] for _ in range(len(s) + 1)]
    prev = [[0 for _ in range(len(t) + 1)] for _ in range(len(s) + 1)]

    for j in range(1, len(s) + 1):
        for i in range(len(s)):
            dp[j][i] = max(dp[j - 1][i], dp[j][i - 1], dp[j - 1][i - 1] + (t_dict[s[i]] == tuple([-1] * len(s_dict[s[i]]))))
            prev[j][i] = max(dp[j-1][i], dp[j-1][i-1])

    # Backtrack to find the actual lengths of longest common subsequence
    q = deque(t_dict[s[-1]])
    for k in range(len(s) - 1, -1, -1):
        if t_dict[s[k]]:
            letter = t_dict[s[k]].popleft()
            curr = s_dict[s[k]][prev[q[0]][letter]]
            q.extend(curr)
            s_dict[s[k]].remove(letter)
            if not s_dict[s[k]]:
                del s_dict[s[k]]

    length = []
    for i in range(len(s[:len(q)]) - 1, -1, -1):
        length.append(len(q[i]))

    return max(length)

