    weight = defaultdict(int)
    for u, v, w, p in tree:
        if p < weight[u] + w:
            return False
        weight[u] += p
    return True

def rebuild_tree(tree, u, w, p):
    if u == 1:  # Check if the tree is unbroken when u is the root
        return True, w, p
    w, p = w - p, p - 1
    for v in tree[(u, 0)]:  # Parent's children
        if rebuild_tree(tree, v, w, p):
            return False, w, p
    return True, w, p

