class BankDatabase:
    def __init__(self, a):
        self.a = self.encode(a)
        self.changed_dig = {}

    def encode(self, a):
        encoded = []
        for i in range(len(a)):
            encoded.append(a[i])
            encoded.append(self.encode_digit(a[i]))
        return encoded

    def decode(self, encoded):
        decoded = []
        for i in encoded:
            if i is None:
                decoded.append(0)
            else:
                decoded.append(self.decode_digit(i))
        return decoded

    def encode_digit(self, n):
        if n == 0:
            return [0] * 10
        digits = []
        last_digit = None

        while n > 0:
            digit = n % 10
            if not self.changed_dig or last_digit != digit and last_digit is not None:
                digits.append(self.encode_digit(last_digit))
                digits.append(self.encode_digit(digit))
                last_digit = digit
            else:
                digits.append(self.encode_digit(digit))
            n //= 10

        return digits

    def decode_digit(self, n):
        if n is None:
            return 0

        decoded = n
        for d in n:
            last = self.decode_digit(d)
            if last is not None:
                decoded *= 10
                decoded += last
            last_digit = decoded
        return last_digit

    def change_digit(self, i, x):
        last_digit = self.decode_digit(self.a[i])
        self.changed_dig[i] = x
        self.a[i] ^= (1 << 15)*x + 1
        self.a[i] &= ~self.encode_digit(last_digit)

    def get_sum(self):
        left = 0
        right_sum = 0
        for i in range(len(self.a) - 1, -1, -1):
            if i < len(self.a):
                right_sum = (right_sum + self.a[i] << 15) & ~self.round_down(1, self.a[i])
            right_sum &= ~self.round_up(self.a[i], self.a[i] << 15)
            if i & 15:
                left = (left << 15) + self.decode_digit(right_sum & self.encode_digit(0))
            right_sum >>= 1
            if right_sum == 0:
                right_sum = 1
        return left

    def round_up(self, n, m):
        m <<= 15
        if m >> 15 > n:
            m += m >> 1
        n <<= 15
        n &= ~m
        return n

    def round_down(self, n, m):
        m >>= 1
        if m >> 15 < n:
            m &= (m - 1)
        m |= 1
        n >>>= 1
        return n & m

