from collections import defaultdict
from heapq import heapify, heappop, heappush

def solve(n, edges):
    graph = defaultdict(list)
    known_students = set()
    for student in range(1, n + 1):
        known_students.add(student)

    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
        known_students.discard(u)
        known_students.discard(v)

    if not known_students:
        return 0, []

    min_heap = []
    for student, known in sorted(known_students):
        if not min_heap:
            heappush(min_heap, (1, (student, student)))  # Special case for unluckiest student
        else:
            last_student, last_souvenir = heappop(min_heap)
            if last_souvenir[1] != known:
                heappush(min_heap, (last_souvenir[0] + 1, (known, student)))

    if not min_heap:
        return 0, []

    known_students.update((student for student, _ in min_heap))
    unknown_students = known_students - set((student, known) for student, known in min_heap)

    result = []
    for known in unknown_students:
        if (known, student) in min_heap:
            result.append((student, known))

    sorted_result = sorted(result, key=lambda x: (-x[1], x[0]))

    unluckiest_student = (student, known) for student, known in sorted_result
    return min((last_souvenir[1] for _, last_souvenir in sorted_result)), sorted(unluckiest_student)

