            if line[0] == '1':
                l, r, changes = int(line[1]) - 1, int(line[2]) - 1, int(line[3])
                changed_serial = apply_change(serial, [(l, r, changes)])
                for i in range(l-1, r):
                    if not check_period(check_d[i], str(changed_serial[i])):
                        print("NO")
                        exit()
                print("YES")
            elif line[0] == '2':
                l, r, d = int(line[1]) - 1, int(line[2]) - 1, int(line[3])
                if check_period(d, str(serial[l:r+1])):
                    print("NO")
                else:
                    checker = serial[l:r+1]
                    # Append changes to checker
                    checker = checker.replace("9" * d, "8" * d).replace("8" * d, "7" * d).replace("7" * d, "6" * d).replace("6" * d, "5" * d).replace("5" * d, "4" * d).replace("4" * d, "3" * d).replace("3" * d, "2" * d).replace("2" * d, "1" * d)
                    for i in range(r, len(serial)):
                        if not check_period(d, checker[i-r+1:]):
                            print("NO")
                            exit()
                    unchanger = apply_change(serial, [(l, r, 1)])
                    changed = apply_change(unchanger, [(l, r, changes)])
                    for i in range(l-1, r):
                        if not check_period(check_d[i], str(changed[i])):
                            print("NO")
                            exit()
        else:
            continue

