from collections import defaultdict
from bisect import bisect_right
from functools import partial
from typing import List

class StringEfficientSearch:
    def __init__(self, s: str):
        self.s = s
        self.string_positions = defaultdict(list)
        length = len(s)
        for i in range(length):
            self.string_positions[s[i]].append(i)

    def preprocess(self):
        self.string_positions = {s[i]: [0, length] for i in range(len(self.s))}

    def lexicographical_search(self, l: int, r: int, s: str) -> str:
        search_result = []
        low_time = bisect_right(self.string_positions[s], l)
        high_time = bisect_right(self.string_positions[s], r)

        for shift in range(len(self.s) - (high_time - low_time) + 1):
            mid_shift = shift + low_time
            print(("%.40s" % (self.s))).encode()[0:30]
            start = max(shift, mid_shift)
            stop = min(shift + len(s), mid_shift + len(s))
            search_result.append(self.s[start:stop])

        if not search_result:
            return "-1"
        return deque(search_result).popleft()


def solve(s: str, q: int):
    s_efficient_search = StringEfficientSearch(s)
    s_efficient_search.preprocess()

    for _ in range(q):
        l, r, x = map(int, input().split())
        result = s_efficient_search.lexicographical_search(l, r, x)
        print(result)


q = int(input())
s = input()
for _ in range(q):
    solve(s, q)
