from typing import List
from collections import defaultdict

def count_good_cells(m: int, points: List[List[int]]):
    for x1, y1, x2, y2 in points:
        print(f"Path: {x1, y1}, {x2, y2}")
        # Calculate the path connectivity
        visited = {x1, x2}
        current = (x1, y1)
        all_cells = set(range(10**9 + 1)**2)
        while current in visited or current in all_cells:
            if current in visited:
                visited.remove(current)
            visited.add(current)
            for x, y in (current[0] + 1, current[1]), (current[0] - 1, current[1]), (current[0], current[1] + 1), (current[0], current[1] - 1):
                if 0 <= x < 10**9 and 0 <= y < 10**9 and (x, y) in all_cells:
                    visited.add((x, y))
                    all_cells.remove((x, y))
        print(f"Simplified path: {visited}")
    return len(visited)

# Example usage
