def find_lca(root):
    if root == 1:
        return 1
    parent = root // 2
    if root % 2 == 0:
        return find_lca(parent)
    else:
        return find_lca(parent + 1)

def find_root(n, queries):
    for query in queries:
        u, v, w = query
        if u == v or v == w or u == w:
            return 'INVALID QUERY'
        if u == w:
            return find_lca(w)
        if v == w:
            return find_lca(w)
        # Check for odd tree case and return lca(w)
    return 'INVALID QUERY'

